// @toreview
"use client"

/**
 * @fileoverview Drawer — slide-in panel powered by Vaul with touch-gesture support.
 * @module packages/ui/components/ui/drawer
 * @layer core
 *
 * Self-contained implementation built on the Vaul drawer primitive. Provides
 * a mobile-friendly slide-up panel with drag-to-dismiss gesture, overlay
 * backdrop, and composable header/footer/content slots.
 *
 * @requires vaul — peer dependency.
 *
 * @component
 * @example
 * import { Drawer, DrawerTrigger, DrawerContent, DrawerHeader, DrawerTitle } from "@saasflare/ui";
 *
 * <Drawer>
 *   <DrawerTrigger asChild><Button>Open Drawer</Button></DrawerTrigger>
 *   <DrawerContent>
 *     <DrawerHeader><DrawerTitle>Settings</DrawerTitle></DrawerHeader>
 *   </DrawerContent>
 * </Drawer>
 */

import * as React from "react"
import { Drawer as DrawerPrimitive } from "vaul"
import { cn } from "@saasflare/ui"
import { useSaasflareProps, type SaasflareComponentProps } from "@saasflare/ui"

/** Root drawer state container; orchestrates open state and gesture context. */
function Drawer({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Root>) {
  return <DrawerPrimitive.Root data-slot="drawer" {...props} />
}

/** Interactive element that toggles the drawer open. Use `asChild` to wrap a custom control. */
function DrawerTrigger({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Trigger>) {
  return <DrawerPrimitive.Trigger data-slot="drawer-trigger" {...props} />
}

/** Portals drawer content (overlay + panel) outside the DOM hierarchy. */
function DrawerPortal({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Portal>) {
  return <DrawerPrimitive.Portal data-slot="drawer-portal" {...props} />
}

/** Element that closes the drawer when activated. Use `asChild` to wrap a custom control. */
function DrawerClose({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Close>) {
  return <DrawerPrimitive.Close data-slot="drawer-close" {...props} />
}

/** Dimmed backdrop rendered behind the drawer panel. */
function DrawerOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Overlay>) {
  return (
    <DrawerPrimitive.Overlay
      data-slot="drawer-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-black/50 backdrop-blur-[2px]",
        className
      )}
      {...props}
    />
  )
}

/** Props for {@link DrawerContent}; adds the surface/radius/animated design-system axes. */
interface DrawerContentProps
  extends Omit<React.ComponentProps<typeof DrawerPrimitive.Content>, keyof SaasflareComponentProps>,
    SaasflareComponentProps {}

/** Sliding panel surface that holds the drawer body; carries the surface/radius/animated axes. */
function DrawerContent({
  className,
  children,
  surface,
  radius,
  animated,
  iconWeight,
  ...props
}: DrawerContentProps) {
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })

  return (
    <DrawerPortal>
      <DrawerOverlay />
      <DrawerPrimitive.Content
        {...props}
        data-slot="drawer-content"
        data-surface={sf.surface}
        data-radius={sf.radius}
        data-animated={String(sf.animated)}
        className={cn(
          "group/drawer-content fixed inset-x-0 bottom-0 z-50 mt-24 flex max-h-[96dvh] flex-col rounded-t-lg border-t surface-card",
          className
        )}
      >
        <div className="mx-auto mt-4 h-1.5 w-12 shrink-0 rounded-full bg-muted" />
        {children}
      </DrawerPrimitive.Content>
    </DrawerPortal>
  )
}

/** Vertical layout slot for the drawer's title and description. */
function DrawerHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-header"
      className={cn("flex flex-col gap-1.5 p-4", className)}
      {...props}
    />
  )
}

/** Bottom-pinned layout slot for drawer actions. */
function DrawerFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-footer"
      className={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  )
}

/** Accessible heading for the drawer, announced to assistive technology. */
function DrawerTitle({
  className,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Title>) {
  return (
    <DrawerPrimitive.Title
      data-slot="drawer-title"
      className={cn("text-lg leading-none font-semibold", className)}
      {...props}
    />
  )
}

/** Supporting descriptive text for the drawer, associated with the title for accessibility. */
function DrawerDescription({
  className,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Description>) {
  return (
    <DrawerPrimitive.Description
      data-slot="drawer-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerOverlay,
  DrawerPortal,
  DrawerTitle,
  DrawerTrigger,
  type DrawerContentProps,
}
